   dict(nome=T('Formaggi','Cheeses','Käse','Fromages'), testo=T("Il pecorino viene dai Monti Sibillini.","Pecorino comes from the Sibillini Mountains.","Der Pecorino stammt aus den Monti Sibillini.","Le pecorino vient des Monts Sibyllins.")),
